// FASE 1: Captura en tiempo real de acciones individuales
const action = $json.action || {};
const sessionData = $json.sessionData || {};
const sessionId = sessionData.sessionId || $json.sessionId || `session_${Date.now()}`;

// Validar que tenemos una acción válida
if (!action.type || !action.timestamp) {
  return [{
    json: {
      success: false,
      error: 'Invalid action data',
      received: $json
    }
  }];
}

// Preparar datos para almacenamiento
const actionData = {
  sessionId: sessionId,
  action: {
    ...action,
    capturedAt: new Date().toISOString(),
    url: sessionData.url || '',
    title: sessionData.title || ''
  },
  metadata: {
    userAgent: $json.userAgent || '',
    timestamp: Date.now()
  }
};

console.log('📝 Action captured for session:', sessionId, 'Action:', action.type);

return [{json: actionData}];

// Respuesta para la fase de captura
const response = {
  success: true,
  message: 'Action stored successfully',
  sessionId: $json.sessionId,
  actionType: $json.action?.type,
  timestamp: new Date().toISOString()
};

return [{json: response}];

// FASE 2: Preparar generación de tests
const sessionId = $json.sessionId;

if (!sessionId) {
  throw new Error('Session ID is required for test generation');
}

console.log('🚀 Starting test generation for session:', sessionId);

// Pasar el sessionId para recuperar las acciones almacenadas
return [{
  json: {
    sessionId: sessionId,
    requestData: $json,
    startTime: new Date().toISOString()
  }
}];

// Procesar acciones almacenadas y preparar para IA
const sessionId = $('Prepare Test Generation').item.json.sessionId;
const rawData = $json.value || '';

if (!rawData || rawData.trim() === '') {
  return [{
    json: {
      success: false,
      error: 'No actions found for session',
      sessionId: sessionId
    }
  }];
}

// Parsear las acciones almacenadas (cada línea es un JSON)
const actions = [];
const lines = rawData.trim().split('\n');

for (const line of lines) {
  if (line.trim()) {
    try {
      const actionData = JSON.parse(line);
      if (actionData.action) {
        actions.push(actionData.action);
      }
    } catch (e) {
      console.log('Skipping invalid action line:', line);
    }
  }
}

// Validar que tenemos suficientes acciones
if (actions.length < 2) {
  return [{
    json: {
      success: false,
      error: 'Insufficient actions for test generation',
      actionsFound: actions.length,
      minimumRequired: 2
    }
  }];
}

// Ordenar acciones por timestamp
actions.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

// Enriquecer con metadata
const enrichedData = {
  sessionId: sessionId,
  totalActions: actions.length,
  processedAt: new Date().toISOString(),
  sourceUrl: actions[0]?.url || '',
  pageTitle: actions[0]?.title || '',
  actions: actions.map((action, index) => ({
    ...action,
    actionIndex: index + 1,
    relativeTime: action.timestamp ? action.timestamp - actions[0].timestamp : 0
  }))
};

console.log('✅ Processed', actions.length, 'actions for generation');

return [{json: enrichedData}];

