// Procesar respuesta de Gemini para Playwright
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const sessionData = $('Process Session Actions').item.json;

// Limpiar y formatear código
const cleanCode = response
  .replace(/```typescript/gi, '')
  .replace(/```javascript/gi, '')
  .replace(/```/g, '')
  .trim();

// Validar que contiene código Playwright
const isValidPlaywright = cleanCode.includes('page.') && 
                         (cleanCode.includes('test(') || cleanCode.includes('test.describe'));

if (!isValidPlaywright) {
  throw new Error('Generated code is not valid Playwright test');
}

return [{
  json: {
    testType: 'playwright',
    generatedCode: cleanCode,
    filename: `playwright-test-${sessionData.sessionId}-${Date.now()}.spec.ts`,
    sessionId: sessionData.sessionId,
    generatedAt: new Date().toISOString(),
    codeLength: cleanCode.length,
    linesCount: cleanCode.split('\n').length,
    sourceActions: sessionData.totalActions
  }
}];

// Procesar respuesta de Gemini para CSV
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const sessionData = $('Process Session Actions').item.json;

// Limpiar CSV
const cleanCsv = response
  .replace(/```csv/gi, '')
  .replace(/```/g, '')
  .trim();

// Validar formato CSV
const lines = cleanCsv.split('\n').filter(line => line.trim());
const hasHeader = lines[0] && lines[0].includes('Step') && lines[0].includes('Action');

if (!hasHeader || lines.length < 2) {
  throw new Error('Generated CSV is not valid');
}

return [{
  json: {
    testType: 'manual',
    generatedCsv: cleanCsv,
    filename: `manual-test-${sessionData.sessionId}-${Date.now()}.csv`,
    sessionId: sessionData.sessionId,
    generatedAt: new Date().toISOString(),
    stepsCount: lines.length - 1,
    csvSize: cleanCsv.length,
    sourceActions: sessionData.totalActions
  }
}];

// Crear respuesta final integrada
const playwrightData = $input.first()?.json || {};
const csvData = $input.last()?.json || {};
const sessionData = $('Process Session Actions').item.json;

// Estadísticas de análisis
const analysis = {
  actionTypes: {},
  selectorTypes: {},
  avgTimeBetweenActions: 0,
  sessionDuration: 0
};

// Analizar tipos de acciones
sessionData.actions.forEach(action => {
  analysis.actionTypes[action.type] = (analysis.actionTypes[action.type] || 0) + 1;

  // Analizar tipos de selectores
  if (action.selector) {
    if (action.selector.startsWith('#')) {
      analysis.selectorTypes.id = (analysis.selectorTypes.id || 0) + 1;
    } else if (action.selector.startsWith('.')) {
      analysis.selectorTypes.class = (analysis.selectorTypes.class || 0) + 1;
    } else if (action.selector.includes(':nth-child')) {
      analysis.selectorTypes.nthChild = (analysis.selectorTypes.nthChild || 0) + 1;
    } else {
      analysis.selectorTypes.other = (analysis.selectorTypes.other || 0) + 1;
    }
  }
});

// Calcular tiempo promedio entre acciones
if (sessionData.actions.length > 1) {
  const lastAction = sessionData.actions[sessionData.actions.length - 1];
  const firstAction = sessionData.actions[0];
  analysis.sessionDuration = lastAction.relativeTime || 0;
  analysis.avgTimeBetweenActions = Math.round(analysis.sessionDuration / (sessionData.actions.length - 1));
}

const finalResult = {
  success: true,
  sessionId: sessionData.sessionId,
  message: 'Tests generated successfully from captured session',
  processedAt: new Date().toISOString(),
  source: {
    url: sessionData.sourceUrl,
    title: sessionData.pageTitle,
    totalActions: sessionData.totalActions
  },
  analysis,
  tests: {
    playwright: {
      code: playwrightData.generatedCode || '',
      filename: playwrightData.filename || '',
      linesCount: playwrightData.linesCount || 0
    },
    manual: {
      csv: csvData.generatedCsv || '',
      filename: csvData.filename || '',
      stepsCount: csvData.stepsCount || 0
    }
  },
  metrics: {
    totalActions: sessionData.totalActions,
    playwrightCodeLength: playwrightData.codeLength || 0,
    csvSize: csvData.csvSize || 0,
    sessionDuration: analysis.sessionDuration,
    processingTime: Date.now() - new Date(sessionData.processedAt).getTime()
  }
};

return [{json: finalResult}];

// Error handler para datos insuficientes
const sessionData = $('Process Session Actions').item.json;

const errorResponse = {
  success: false,
  error: 'Insufficient session data for test generation',
  message: sessionData.error || 'At least 2 actions are required to generate meaningful tests',
  sessionId: sessionData.sessionId,
  actionsFound: sessionData.totalActions || 0,
  minimumRequired: 2,
  suggestions: [
    'Perform more interactions during recording session',
    'Ensure actions are being captured properly',
    'Try recording a complete user workflow'
  ]
};

return [{json: errorResponse}];
